<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Support\Audits;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;

class GovernanceController extends Controller
{
    public function roles() { return response()->json(['data'=>DB::table('roles')->orderBy('name')->get()]); }
    public function permissions() { return response()->json(['data'=>DB::table('permissions')->orderBy('module')->orderBy('code')->get()]); }
    public function assignRoles(Request $r,int $id) { $d=$r->validate(['role_ids'=>'required|array|min:1','role_ids.*'=>'exists:roles,id','office_id'=>'nullable|exists:offices,id']); abort_unless(DB::table('users')->where('id',$id)->exists(),404); DB::transaction(function()use($r,$id,$d){DB::table('user_roles')->where('user_id',$id)->delete();foreach($d['role_ids']as$role)DB::table('user_roles')->insert(['user_id'=>$id,'role_id'=>$role,'office_id'=>$d['office_id']??null,'assigned_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$primaryRole=DB::table('roles')->where('id',$d['role_ids'][0])->value('code');DB::table('users')->where('id',$id)->update(['role'=>$primaryRole,'office_id'=>$d['office_id']??null,'updated_at'=>now()]);});Audits::write($r,'assign_roles','users',$id,$d);return response()->noContent(); }
    public function settings() { return response()->json(['data'=>DB::table('system_settings')->select('setting_key','value_json','is_secret','updated_at')->get()]); }
    public function updateSetting(Request $r,string $key) { $d=$r->validate(['value'=>'required']); DB::table('system_settings')->updateOrInsert(['setting_key'=>$key],['value_json'=>json_encode($d['value']),'updated_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);Audits::write($r,'update_setting','system_settings',null,['key'=>$key]);return response()->json(['data'=>['setting_key'=>$key,'value'=>$d['value']]]); }
    public function preference(Request $r) { $d=$r->validate(['event_key'=>'required|string|max:100','in_app_enabled'=>'boolean','email_enabled'=>'boolean','sms_enabled'=>'boolean']); DB::table('notification_preferences')->updateOrInsert(['user_id'=>$r->user()->id,'event_key'=>$d['event_key']],['in_app_enabled'=>$d['in_app_enabled']??true,'email_enabled'=>$d['email_enabled']??false,'sms_enabled'=>$d['sms_enabled']??false,'created_at'=>now(),'updated_at'=>now()]); return response()->noContent(); }
    public function amendments(Request $r,int $contract) { return response()->json(['data'=>DB::table('contract_amendments')->where('contract_id',$contract)->latest()->get()]); }
    public function createAmendment(Request $r,int $contract) { $d=$r->validate(['amendment_no'=>'required|string|max:100','reason'=>'required|string','amount_delta'=>'nullable|numeric','new_amount'=>'nullable|numeric|gt:0','new_end_date'=>'nullable|date']);$id=DB::table('contract_amendments')->insertGetId([...$d,'contract_id'=>$contract,'amount_delta'=>$d['amount_delta']??0,'status'=>'draft','created_at'=>now(),'updated_at'=>now()]);Audits::write($r,'create_amendment','contract_amendments',$id,$d);return response()->json(['data'=>DB::table('contract_amendments')->where('id',$id)->first()],201); }
    public function approveAmendment(Request $r,int $id) { return DB::transaction(function()use($r,$id){$a=DB::table('contract_amendments')->where('id',$id)->first();abort_unless($a,404);$contract=DB::table('contracts')->where('id',$a->contract_id)->lockForUpdate()->first();$values=['updated_at'=>now()];if($a->new_amount!==null){$values['amount']=$a->new_amount;$values['tier']=$a->new_amount<5000?'tier1':($a->new_amount<50000?'tier2':($a->new_amount<500000?'tier3':'tier4'));}if($a->new_end_date)$values['end_date']=$a->new_end_date;DB::table('contracts')->where('id',$a->contract_id)->update($values);DB::table('contract_amendments')->where('id',$id)->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);Audits::write($r,'approve_amendment','contract_amendments',$id,['contract_id'=>$a->contract_id]);return response()->json(['data'=>DB::table('contract_amendments')->where('id',$id)->first()]);}); }
    public function report(Request $r,string $code) { $allowed=['contracts','orders','companies','inventory'];abort_unless(in_array($code,$allowed,true),404);$table=['contracts'=>'contracts','orders'=>'procurement_orders','companies'=>'companies','inventory'=>'inventory_items'][$code];$q=DB::table($table);if(in_array($table,['contracts','procurement_orders','companies','inventory_items'],true))$q->whereNull('deleted_at');foreach(['status','company_id','office_id']as$f)if($r->filled($f))$q->where($f,$r->input($f));$rows=$q->get();if($r->input('format')==='csv'){ $file="exports/{$code}-".Str::uuid().'.csv';$csv=fopen('php://temp','r+');if($rows->isNotEmpty()){fputcsv($csv,array_keys((array)$rows->first()));foreach($rows as$row)fputcsv($csv,(array)$row);}rewind($csv);Storage::disk('local')->put($file,stream_get_contents($csv));fclose($csv);$id=DB::table('export_jobs')->insertGetId(['requested_by'=>$r->user()->id,'report_code'=>$code,'format'=>'csv','parameters_json'=>json_encode($r->query()),'status'=>'completed','storage_path'=>$file,'expires_at'=>now()->addDay(),'created_at'=>now(),'updated_at'=>now()]);Audits::write($r,'export',$table,null,['export_job_id'=>$id]);return response()->json(['data'=>['exportJobId'=>$id,'downloadUrl'=>url("/api/v1/exports/{$id}/download")]]);}return response()->json(['data'=>$rows,'meta'=>['count'=>$rows->count(),'report'=>$code]]); }
    public function downloadExport(int $id) { $job=DB::table('export_jobs')->where('id',$id)->where('status','completed')->first();abort_unless($job&&Storage::disk('local')->exists($job->storage_path),404);return Storage::disk('local')->download($job->storage_path); }
    public function createBackup(Request $r) { $tables=['office_categories','offices','companies','vendors','procurement_orders','rfqs','bids','contracts','inventory_items','inventory_movements'];$snapshot=[];foreach($tables as$table)$snapshot[$table]=DB::table($table)->get();$json=json_encode(['created_at'=>now()->toIso8601String(),'data'=>$snapshot],JSON_PRETTY_PRINT);$path='backups/procurement-'.Str::uuid().'.json';Storage::disk('local')->put($path,$json);$id=DB::table('backups')->insertGetId(['storage_path'=>$path,'checksum'=>hash('sha256',$json),'status'=>'completed','created_by'=>$r->user()->id,'retention_until'=>now()->addDays(30),'created_at'=>now(),'updated_at'=>now()]);Audits::write($r,'backup','backups',$id);return response()->json(['data'=>DB::table('backups')->where('id',$id)->first()],201); }
    public function backups() { return response()->json(['data'=>DB::table('backups')->latest()->get()]); }
}
